insert1='''        val bullReaction=(bullPin||bullEngulf)&&((support!=null&&abs(last.l-support.price)<=a*.28)||nearSupport)\n        val bearReaction=(bearPin||bearEngulf)&&((resistance!=null&&abs(last.h-resistance.price)<=a*.28)||nearResistance)\n\n        // v31 FOUR-VIDEO CONFLUENCE LAYER\n        // Video 1: projected trendline third-touch/retest rejection.\n        // Video 2: liquidity-to-liquidity rotation with a clear opposing objective.\n        // Video 3: broken-level ladder continuation toward the next structure/liquidity level.\n        // Video 4: dominant-wick reclaim / wick-fill rejection.\n        // These are additional setup families and scoring evidence, never universal blockers.\n        val bullTrendlinePrice=projectedTrendline(c,"BUY",a)\n        val bearTrendlinePrice=projectedTrendline(c,"SELL",a)\n        val bullTrendlineReaction=bullTrendlinePrice?.let{line->\n            last.l<=line+a*.20&&last.c>=line-a*.04&&last.c>last.o&&(lowerWick>=body*.70||bullEngulf||pressureBull)\n        }==true\n        val bearTrendlineReaction=bearTrendlinePrice?.let{line->\n            last.h>=line-a*.20&&last.c<=line+a*.04&&last.c<last.o&&(upperWick>=body*.70||bearEngulf||pressureBear)\n        }==true\n\n        val bullWickSource=dominantWickSource(c,"BUY",a)\n        val bearWickSource=dominantWickSource(c,"SELL",a)\n        val bullWickReclaim=bullWickSource?.let{x->\n            val bodyLow=min(x.o,x.c);val wickDepth=(bodyLow-x.l).coerceAtLeast(1e-9)\n            last.l<=bodyLow+a*.10&&last.l>=x.l-a*.10&&last.c>bodyLow+min(a*.08,wickDepth*.18)&&last.c>last.o&&(pressureBull||momentumBull||bullReaction||rsiBullDiv)\n        }==true\n        val bearWickReclaim=bearWickSource?.let{x->\n            val bodyHigh=max(x.o,x.c);val wickDepth=(x.h-bodyHigh).coerceAtLeast(1e-9)\n            last.h>=bodyHigh-a*.10&&last.h<=x.h+a*.10&&last.c<bodyHigh-min(a*.08,wickDepth*.18)&&last.c<last.o&&(pressureBear||momentumBear||bearReaction||rsiBearDiv)\n        }==true\n\n        val bullOppPool=lm.resistances.filter{it.price>last.c+a*.30}.minByOrNull{it.price}\n        val bearOppPool=lm.supports.filter{it.price<last.c-a*.30}.maxByOrNull{it.price}\n        val bullLiquidityRoute=(liqSweepBull||stopHuntBull||fakeBull||multiTouchBull||bullReaction)&&bullOppPool!=null&&(bullOppPool.price-last.c)>=a*.65&&(chochBull||srFlipBull||pressureBull||momentumBull||rsiBullDiv)\n        val bearLiquidityRoute=(liqSweepBear||stopHuntBear||fakeBear||multiTouchBear||bearReaction)&&bearOppPool!=null&&(last.c-bearOppPool.price)>=a*.65&&(chochBear||srFlipBear||pressureBear||momentumBear||rsiBearDiv)\n\n        val bullLadderBase=nearestBrokenResistance(c,a,last.c)\n        val bearLadderBase=nearestBrokenSupport(c,a,last.c)\n        val bullLevelLadder=bullLadderBase!=null&&bullOppPool!=null&&last.c>bullLadderBase&&abs(last.l-bullLadderBase)<=a*.30&&(bullOppPool.price-last.c)>=a*.55&&(pressureBull||momentumBull||displacementBull||bosBull)\n        val bearLevelLadder=bearLadderBase!=null&&bearOppPool!=null&&last.c<bearLadderBase&&abs(last.h-bearLadderBase)<=a*.30&&(last.c-bearOppPool.price)>=a*.55&&(pressureBear||momentumBear||displacementBear||bosBear)\n'''
